import{_ as e,o,c as d,a2 as a}from"./chunks/framework.CRfKVJQk.js";const p=JSON.parse('{"title":"Troubleshooting","description":"Fix common Liquid Glass problems in React Native, Expo and web apps: flat glass on Android, Expo Go fallback, web build errors and performance issues.","frontmatter":{"description":"Fix common Liquid Glass problems in React Native, Expo and web apps: flat glass on Android, Expo Go fallback, web build errors and performance issues.","head":[["link",{"rel":"canonical","href":"https://sachinmeenasipl.github.io/react-native-glass-effect/reference/troubleshooting"}],["meta",{"property":"og:url","content":"https://sachinmeenasipl.github.io/react-native-glass-effect/reference/troubleshooting"}],["meta",{"property":"og:title","content":"Troubleshooting · Liquid Glass for React Native"}],["meta",{"property":"og:description","content":"Fix common Liquid Glass problems in React Native, Expo and web apps: flat glass on Android, Expo Go fallback, web build errors and performance issues."}],["meta",{"name":"twitter:title","content":"Troubleshooting · Liquid Glass for React Native"}],["meta",{"name":"twitter:description","content":"Fix common Liquid Glass problems in React Native, Expo and web apps: flat glass on Android, Expo Go fallback, web build errors and performance issues."}]]},"headers":[],"relativePath":"reference/troubleshooting.md","filePath":"reference/troubleshooting.md"}'),r={name:"reference/troubleshooting.md"};function s(i,t,n,l,c,h){return o(),d("div",null,[...t[0]||(t[0]=[a('<h1 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h1><p>First step on Android: <code>adb logcat -s LiquidGlass</code>. Most problems print a one-line explanation there.</p><h2 id="setup" tabindex="-1">Setup <a class="header-anchor" href="#setup" aria-label="Permalink to &quot;Setup&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Symptom</th><th>Cause</th><th>Fix</th></tr></thead><tbody><tr><td>Warning &quot;Native code not found&quot;</td><td>The app wasn&#39;t rebuilt, or it&#39;s Expo Go</td><td>Rebuild (<code>run-android</code>, or <code>pod install</code> + <code>run-ios</code>). In Expo, use a dev build</td></tr><tr><td><code>isNativeAvailable</code> is <code>false</code> on a phone</td><td>Same as above</td><td>See <a href="/react-native-glass-effect/installation/verify">Verify the install</a></td></tr><tr><td>Expo Go shows a plain tinted box, no blur</td><td>Expo Go can&#39;t load third-party native code</td><td>Use a dev build: <code>npx expo run:android</code> / <code>run:ios</code>, or EAS Build</td></tr><tr><td>Windows, Android build: <code>ninja: error: mkdir(...): No such file or directory</code></td><td>A path longer than 260 characters (project in a deep folder such as OneDrive)</td><td>Enable Windows long paths, or set a short CMake <code>buildStagingDirectory</code>. See <a href="/react-native-glass-effect/installation/expo#windows-android-build-fails-with-ninja-no-such-file-or-directory">Expo</a></td></tr></tbody></table><h2 id="web" tabindex="-1">Web <a class="header-anchor" href="#web" aria-label="Permalink to &quot;Web&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Symptom</th><th>Cause</th><th>Fix</th></tr></thead><tbody><tr><td>Build fails: <code>Could not load react-native/Libraries/...</code></td><td><code>react-native</code> isn&#39;t aliased to <code>react-native-web</code></td><td>Add the alias. See <a href="/react-native-glass-effect/installation/web">Web</a> or <a href="/react-native-glass-effect/installation/nextjs">Next.js</a></td></tr><tr><td><code>global is not defined</code> in the browser (Vite)</td><td>A dependency expects Node&#39;s <code>global</code></td><td>Add <code>define: { global: &#39;globalThis&#39; }</code> to <code>vite.config.js</code></td></tr><tr><td><code>Invalid hook call</code></td><td>Two copies of React (common with linked packages)</td><td>Vite: <code>resolve.dedupe: [&#39;react&#39;, &#39;react-dom&#39;, &#39;react-native-web&#39;]</code></td></tr><tr><td>The page is blank, or content collapses to the top</td><td>The root element has no height</td><td>Vite: a full-height flex root. Next.js: <code>height: &#39;100vh&#39;</code> on <code>&lt;body&gt;</code></td></tr><tr><td>No blur, only tint</td><td>The browser doesn&#39;t support <code>backdrop-filter</code></td><td>Expected; the glass keeps its tint and border</td></tr></tbody></table><h2 id="looks" tabindex="-1">Looks <a class="header-anchor" href="#looks" aria-label="Permalink to &quot;Looks&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Symptom</th><th>Cause</th><th>Fix</th></tr></thead><tbody><tr><td>Glass is a flat, solid colour (Android)</td><td>No <code>GlassBackdrop</code>, or the glass is <strong>inside</strong> it</td><td>Wrap the background in <code>&lt;GlassBackdrop&gt;</code> and render glass next to it. See <a href="/react-native-glass-effect/guide/core-concepts">Core concepts</a></td></tr><tr><td>Solid colour only inside a Modal</td><td>A Modal is a separate window</td><td>Add a <code>GlassBackdrop</code> inside the Modal. See <a href="/react-native-glass-effect/recipes/modal">Glass in a modal</a></td></tr><tr><td>Part of the glass looks empty, tint only</td><td>The glass extends past its backdrop</td><td>Make the backdrop cover the glass (<code>StyleSheet.absoluteFill</code>)</td></tr><tr><td><code>backgroundColor</code> on glass has no effect</td><td>It&#39;s drawn under the blur</td><td>Use <code>tint</code> + <code>tintOpacity</code></td></tr><tr><td>Double border</td><td>Style <code>borderWidth</code> + glass border</td><td>Use the <code>borderWidth</code> <strong>prop</strong>, not the style</td></tr><tr><td>Button label is hard to read</td><td>The default label is dark in light mode</td><td>Set <code>textStyle={{ color: &#39;#fff&#39; }}</code></td></tr><tr><td>Looks flat on Android 12</td><td>No refraction below Android 13 (by design)</td><td>Expected. Raise <code>illumination</code> or <code>borderOpacity</code> for more definition</td></tr><tr><td>Glass looks different on iOS and Android</td><td>iOS uses Apple&#39;s glass by default</td><td>Use <code>FrostedGlass</code> or <code>iosRenderer=&quot;shader&quot;</code>. See <a href="/react-native-glass-effect/reference/platform-support">Platform support</a></td></tr><tr><td>iOS: blur looks wrong while fading glass in or out</td><td>UIKit can&#39;t draw blur correctly at alpha below 1</td><td>Fade the content inside the glass, or scale the glass instead</td></tr><tr><td>Shader never shows on one device model</td><td>The GPU driver rejected the shader; the glass fell back to blur</td><td>Nothing to do: it&#39;s automatic. Report the device model</td></tr></tbody></table><h2 id="content-capture-android" tabindex="-1">Content capture (Android) <a class="header-anchor" href="#content-capture-android" aria-label="Permalink to &quot;Content capture (Android)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Symptom</th><th>Cause</th><th>Fix</th></tr></thead><tbody><tr><td>No blur on Android 11 and older, only a solid colour</td><td>Images loaded as HARDWARE bitmaps can&#39;t be captured in software</td><td>Glide: <code>.disallowHardwareConfig()</code>; Coil: <code>allowHardware(false)</code> for images behind glass</td></tr><tr><td>Video or map behind glass shows black or transparent</td><td>It renders into a <code>SurfaceView</code></td><td>Use texture mode (for example react-native-video <code>useTextureView</code>)</td></tr><tr><td>Glass doesn&#39;t follow a rotated parent (Android 7–9)</td><td>Rotation and scale alignment need Android 10+</td><td>Avoid rotating glass on old Android</td></tr></tbody></table><h2 id="performance" tabindex="-1">Performance <a class="header-anchor" href="#performance" aria-label="Permalink to &quot;Performance&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Symptom</th><th>Cause</th><th>Fix</th></tr></thead><tbody><tr><td>Stutters while an animation plays <strong>under</strong> a glass</td><td>Glass over changing content re-blurs every frame</td><td>Move the animation, or use a smaller blur. Check <code>getGlassStats().gpuBlurPasses</code></td></tr><tr><td>Stutters while scrolling on older phones</td><td>Too many glass views, or the compat tier</td><td><code>quality=&quot;low&quot;</code> or <code>&quot;static&quot;</code>, fewer or smaller glass views</td></tr><tr><td>Squish and transitions don&#39;t animate</td><td>Reduce Motion / Remove animations is on</td><td>Expected (accessibility)</td></tr></tbody></table><h2 id="still-stuck" tabindex="-1">Still stuck? <a class="header-anchor" href="#still-stuck" aria-label="Permalink to &quot;Still stuck?&quot;">​</a></h2><p><a href="https://github.com/SachinMeenaSipl/react-native-glass-effect/issues" target="_blank" rel="noreferrer">Open an issue</a> with: your React Native or Expo version, the device and OS version (or browser), the <code>useGlassCapabilities()</code> output, and the <code>LiquidGlass</code> logcat lines on Android.</p>',14)])])}const b=e(r,[["render",s]]);export{p as __pageData,b as default};
